export function translate(locale, key, params = {}) {
  const template = importMessages[locale]?.[key] || composerMessages[locale]?.[key] || messages[locale]?.[key] || sharedMessages[locale]?.[key] || extraMessages[locale]?.[key] || replyMessages[locale]?.[key] || importMessages.en[key] || composerMessages.en[key] || messages.en[key] || sharedMessages.en[key] || extraMessages.en[key] || replyMessages.en[key] || key
  return template.replace(/\{(\w+)\}/g, (_, name) => String(params[name] ?? ''))
}
